// Query the library version string (static storage)
const char *ver = lwgeom_version();
// Property: version string pointer should be non-null per API docs
FUZZ_ASSERT(ver != nullptr, "lwgeom_version returned null");
// Validation: No persistent objects to return; call is side-effect free.

// Generate a (potentially out-of-range) SRID to exercise clamping/notice paths
int32_t in_srid = (int32_t)(*FUZZ_PARAM(unsigned int));
// Invoke function; it returns a valid SRID per contract (may clamp/raise notice internally)
int32_t out_srid = clamp_srid(in_srid);
(void)out_srid;
// Validation: We don't assert range since policy is library-defined; no persistent objects involved.

// Provide NULL handlers (valid per API: either callable pointers or NULL)
lwallocator alloc_cb = nullptr;
lwreallocator realloc_cb = nullptr;
lwfreeor free_cb = nullptr;
lwreporter err_cb = nullptr;
lwreporter notice_cb = nullptr;
// Install the (null) handlers
lwgeom_set_handlers(alloc_cb, realloc_cb, free_cb, err_cb, notice_cb);
// Validation: Passing NULLs exercises handler registration path safely without requiring real callbacks.

// Register a NULL debug logger (allowed: disables custom logging)
lwdebuglogger dbg = nullptr;
lwgeom_set_debuglogger(dbg);
// Validation: Safe no-op registration; no persistent objects.

// Request interruption (should be safe, async-friendly)
lwgeom_request_interrupt();
// Validation: No return value; side-effect sets global interrupt flag.

// Cancel prior interruption request
lwgeom_cancel_interrupt();
// Validation: No return value; resets global interrupt flag.

// Register a NULL callback (valid; unregisters any existing callback)
lwinterrupt_callback *cb = nullptr;
lwinterrupt_callback *prev = lwgeom_register_interrupt_callback(cb);
(void)prev; // previous may be non-null; not used further in this stub
// Validation: Safe registration path with NULL; no persistent objects.

// Attempt to cast to LWMPOLY; may return NULL if not a multipolygon
LWMPOLY *mp = lwgeom_as_lwmpoly(lwgeom);
(void)mp; // Result is a non-owning view; do not store as a persistent output
// Validation: Input is returned to pool; cast result is ephemeral and may be NULL.

// Attempt to cast to LWMLINE; returns NULL if illegal
LWMLINE *ml = lwgeom_as_lwmline(lwgeom);
(void)ml;
// Validation: Preserve input; cast pointer not persisted since it may be NULL/non-owned.

// Attempt to cast to LWMPOINT; may return NULL
LWMPOINT *mp = lwgeom_as_lwmpoint(lwgeom);
(void)mp;
// Validation: Input geometry is returned; cast result is transient.

// Attempt to cast to LWCOLLECTION; NULL if type is not a collection
LWCOLLECTION *col = lwgeom_as_lwcollection(lwgeom);
(void)col;
// Validation: Only the original input is returned to the pool.

// Attempt to cast to LWPOLY; may return NULL for non-polygon types
LWPOLY *poly = lwgeom_as_lwpoly(lwgeom);
(void)poly;
// Validation: Input preserved; cast is non-owning/optional.

// Attempt to cast to LWLINE; may return NULL
LWLINE *ln = lwgeom_as_lwline(lwgeom);
(void)ln;
// Validation: Input geometry returned; cast pointer is ephemeral.

// Attempt to cast to LWCIRCSTRING; may return NULL
LWCIRCSTRING *cs = lwgeom_as_lwcircstring(lwgeom);
(void)cs;
// Validation: Input preserved; cast pointer not returned.

// Attempt to cast to LWCURVEPOLY; may return NULL
LWCURVEPOLY *cp = lwgeom_as_lwcurvepoly(lwgeom);
(void)cp;
// Validation: Return only the input object to the pool.

// Attempt to cast to LWCOMPOUND; may return NULL
LWCOMPOUND *cc = lwgeom_as_lwcompound(lwgeom);
(void)cc;
// Validation: Input geometry is output; cast pointer is transient.

// Attempt to cast to LWPSURFACE; may return NULL
LWPSURFACE *ps = lwgeom_as_lwpsurface(lwgeom);
(void)ps;
// Validation: Preserve input only.

// Attempt to cast to LWTRIANGLE; may return NULL
LWTRIANGLE *tri = lwgeom_as_lwtriangle(lwgeom);
(void)tri;
// Validation: Input is returned; cast pointer is not persisted.

// Attempt to cast to LWTIN; may return NULL
LWTIN *tin = lwgeom_as_lwtin(lwgeom);
(void)tin;
// Validation: Only the original LWGEOM is output.

// Convert to a multi-geometry equivalent. Always returns a geometry (may clone/convert)
LWGEOM *lwgeom_multi = lwgeom_as_multi(lwgeom);
FUZZ_ASSERT(lwgeom_multi != nullptr, "lwgeom_as_multi must return a geometry");
// Optional: mark result as derived for downstream tracking
FUZZ_SET_ATTR_INT(lwgeom_multi, "derived_from_multi", 1);
// Validation: Both original and newly returned geometry are returned to the pool; ownership of result is with caller.

// Convert to a curve representation; always returns a geometry
LWGEOM *lwgeom_curve = lwgeom_as_curve(lwgeom);
// Validate non-null return per API contract
FUZZ_ASSERT(lwgeom_curve != nullptr, "lwgeom_as_curve must return a geometry");
// Track that this is a derived curved variant to aid downstream logic
FUZZ_SET_ATTR_INT(lwgeom_curve, "derived_curve", 1);
// Validation: return both original (still owned by pool) and the new curved geometry (caller-owned).

// Upcast LWTIN to LWGEOM (non-owning alias)
LWGEOM *as_g = lwtin_as_lwgeom(obj);
FUZZ_ASSERT(as_g != nullptr, "lwtin_as_lwgeom should always succeed");
(void)as_g; // Do not persist alias to avoid double-free risk
// Validation: Only return the original LWTIN back to the pool.

// Upcast LWTRIANGLE to LWGEOM (non-owning alias)
LWGEOM *as_g = lwtriangle_as_lwgeom(obj);
FUZZ_ASSERT(as_g != nullptr, "lwtriangle_as_lwgeom should always succeed");
(void)as_g;
// Validation: Return only the original triangle.

// Upcast LWPSURFACE to LWGEOM (non-owning alias)
LWGEOM *as_g = lwpsurface_as_lwgeom(obj);
FUZZ_ASSERT(as_g != nullptr, "lwpsurface_as_lwgeom should always succeed");
(void)as_g;
// Validation: Return only the original polyhedral surface.

// Upcast LWMPOLY to LWGEOM (non-owning alias)
LWGEOM *as_g = lwmpoly_as_lwgeom(obj);
FUZZ_ASSERT(as_g != nullptr, "lwmpoly_as_lwgeom should always succeed");
(void)as_g;
// Validation: Return only the original multipolygon.

// Upcast LWMLINE to LWGEOM (non-owning alias)
LWGEOM *as_g = lwmline_as_lwgeom(obj);
FUZZ_ASSERT(as_g != nullptr, "lwmline_as_lwgeom should always succeed");
(void)as_g;
// Validation: Return only the original multilinestring.

// Upcast LWMPOINT to LWGEOM (non-owning alias)
LWGEOM *as_g = lwmpoint_as_lwgeom(obj);
FUZZ_ASSERT(as_g != nullptr, "lwmpoint_as_lwgeom should always succeed");
(void)as_g;
// Validation: Return only the original multipoint.

// Upcast LWCOLLECTION to LWGEOM (non-owning alias)
LWGEOM *as_g = lwcollection_as_lwgeom(obj);
FUZZ_ASSERT(as_g != nullptr, "lwcollection_as_lwgeom should always succeed");
(void)as_g;
// Validation: Return only the original collection.

// Upcast LWCIRCSTRING to LWGEOM (non-owning alias)
LWGEOM *as_g = lwcircstring_as_lwgeom(obj);
FUZZ_ASSERT(as_g != nullptr, "lwcircstring_as_lwgeom should always succeed");
(void)as_g;
// Validation: Return only the original circularstring.

// Upcast LWCOMPOUND to LWGEOM (non-owning alias)
LWGEOM *as_g = lwcompound_as_lwgeom(obj);
FUZZ_ASSERT(as_g != nullptr, "lwcompound_as_lwgeom should always succeed");
(void)as_g;
// Validation: Return only the original compound curve.

// Upcast LWCURVEPOLY to LWGEOM (non-owning alias)
LWGEOM *as_g = lwcurvepoly_as_lwgeom(obj);
FUZZ_ASSERT(as_g != nullptr, "lwcurvepoly_as_lwgeom should always succeed");
(void)as_g;
// Validation: Return only the original curve polygon.

// Upcast LWPOLY to LWGEOM (non-owning alias)
LWGEOM *as_g = lwpoly_as_lwgeom(obj);
FUZZ_ASSERT(as_g != nullptr, "lwpoly_as_lwgeom should always succeed");
(void)as_g;
// Validation: Return only the original polygon.

// Upcast LWLINE to LWGEOM (non-owning alias)
LWGEOM *as_g = lwline_as_lwgeom(obj);
FUZZ_ASSERT(as_g != nullptr, "lwline_as_lwgeom should always succeed");
(void)as_g;
// Validation: Return only the original linestring.

// Upcast LWPOINT to LWGEOM (non-owning alias)
LWGEOM *as_g = lwpoint_as_lwgeom(obj);
FUZZ_ASSERT(as_g != nullptr, "lwpoint_as_lwgeom should always succeed");
(void)as_g;
// Validation: Return only the original point.

// Append a geometry to the collection; may reallocate the collection object
LWCOLLECTION *new_col = lwcollection_add_lwgeom(col, geom);
// new_col must be used going forward (address may change)
if (!new_col) { FUZZ_BAIL(); }
// Optionally track current count for downstream validation
int n = lwcollection_ngeoms(new_col);
FUZZ_SET_ATTR_INT(new_col, "ngeoms", n);
// Output: updated collection and original geom (const in API; ownership not transferred).

// Append a LWPOINT into a LWMPOINT; container may be reallocated
LWMPOINT *new_mobj = lwmpoint_add_lwpoint(mobj, obj);
if (!new_mobj) { FUZZ_BAIL(); }
// Track element count if available through collection helpers is not directly exposed; store a bump hint
FUZZ_SET_ATTR_INT(new_mobj, "maybe_ngeoms_inc", 1);
// Return updated multipoint and keep original point (input was const; ownership not transferred).

// Append an LWLINE into a LWMLINE; container may be reallocated
LWMLINE *new_mobj = lwmline_add_lwline(mobj, obj);
if (!new_mobj) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(new_mobj, "maybe_ngeoms_inc", 1);
// Output updated multilinestring and keep original line.

// Append an LWPOLY into a LWMPOLY; container may be reallocated
LWMPOLY *new_mobj = lwmpoly_add_lwpoly(mobj, obj);
if (!new_mobj) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(new_mobj, "maybe_ngeoms_inc", 1);
// Output updated multipolygon and keep original polygon.

// Append an LWPOLY into a LWPSURFACE; container may be reallocated
LWPSURFACE *new_mobj = lwpsurface_add_lwpoly(mobj, obj);
if (!new_mobj) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(new_mobj, "maybe_ngeoms_inc", 1);
// Output updated polyhedral surface and keep original polygon.

// Append an LWTRIANGLE into a LWTIN; container may be reallocated
LWTIN *new_mobj = lwtin_add_lwtriangle(mobj, obj);
if (!new_mobj) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(new_mobj, "maybe_ngeoms_inc", 1);
// Output updated TIN and keep original triangle.

// Concatenate col2 into col1 in place; col1 may be reallocated
LWCOLLECTION *new_col1 = lwcollection_concat_in_place(col1, col2);
if (!new_col1) { FUZZ_BAIL(); }
// Track resulting geometry count for downstream validations/decisions
int n1 = lwcollection_ngeoms(new_col1);
FUZZ_SET_ATTR_INT(new_col1, "ngeoms", n1);
// Output: updated col1 (possibly reallocated) and original col2 (unchanged)
col1 = new_col1;
// Validation: Ensured non-null return and tracked size; address change handled by reassigning col1.

// Randomly generate boolean flags for Z/M/geodetic
int hasz = (int)(*FUZZ_PARAM(unsigned int) % 2);
int hasm = (int)(*FUZZ_PARAM(unsigned int) % 2);
int geodetic = (int)(*FUZZ_PARAM(unsigned int) % 2);
// Build the flags mask; return value is not persisted
lwflags_t fl = lwflags(hasz, hasm, geodetic);
(void)fl;
// Validation: Inputs constrained to 0/1; function is pure, no persistent objects.

// Extract lwflags from GSERIALIZED header
lwflags_t f = gserialized_get_lwflags(g);
(void)f;
// Validation: Non-owning read of g; return g to pool unchanged.

// Attempt to read embedded float bbox pointer and ndims
size_t ndims = 0;
const float *fp = gserialized_get_float_box_p(g, &ndims);
// If fp is non-null, ndims should have been set; we do not dereference fp
if (fp) { (void)ndims; }
// Validation: Safe metadata access; g is returned unchanged.

// Read geometry type code from header
uint32_t t = gserialized_get_type(g);
(void)t;
// Validation: Non-owning header read; return g unchanged.

// Query maximum header size for GSERIALIZED parsing
uint32_t hs = gserialized_max_header_size();
(void)hs;
// Validation: Pure query; no persistent objects involved.

// Compute a stable-ish content hash for the geometry
int32_t h = gserialized_hash(g);
(void)h;
// Validation: Read-only operation; g is returned unchanged.

// Extract SRID from packed header
int32_t srid = gserialized_get_srid(g);
(void)srid;
// Validation: Non-owning read; return g unchanged.

// Generate an SRID (range policy is library-defined)
int32_t srid = (int32_t)(*FUZZ_PARAM(unsigned int));
// Set SRID in place; g must be writable per API
gserialized_set_srid(g, srid);
// Validation: In-place modification only; return same GSERIALIZED back to pool.

// Check if top-level geometry is empty
int empty = gserialized_is_empty(g);
(void)empty;
// Validation: Read-only check; g returned unchanged.

// Test for presence of embedded bbox
int has = gserialized_has_bbox(gser);
(void)has;
// Validation: Header inspection only; return input GSERIALIZED.

// Test if geometry has Z ordinate
int hz = gserialized_has_z(gser);
(void)hz;
// Validation: Header inspection; return input unchanged.

// Test if geometry has M ordinate
int hm = gserialized_has_m(gser);
(void)hm;
// Validation: Header inspection; return input unchanged.

// Test if geometry is geodetic
int geo = gserialized_is_geodetic(gser);
(void)geo;
// Validation: Header inspection; return input unchanged.

// Determine dimensionality encoded in GSERIALIZED
int nd = gserialized_ndims(gser);
(void)nd;
// Validation: Header inspection; return input unchanged.

// Three-way comparison (-1,0,1) using library ordering semantics
int c = gserialized_cmp(g1, g2);
(void)c;
// Validation: Non-owning comparisons; both inputs returned unchanged.

// Serialize LWGEOM into GSERIALIZED; library allocates the buffer
size_t out_size = 0;
GSERIALIZED *gser = gserialized_from_lwgeom(geom, &out_size);
if (!gser) { FUZZ_BAIL(); }
// Track size metadata for downstream users
FUZZ_SET_ATTR_INT(gser, "size", (int)out_size);
// Validation: Non-null result asserted; ownership of result passed back via outputs.

// Deserialize GSERIALIZED into a newly allocated LWGEOM
LWGEOM *lwgeom = lwgeom_from_gserialized(g);
if (!lwgeom) { FUZZ_BAIL(); }
// Optionally record that this LWGEOM was deserialized
